import os
import torch
import random
import numpy as np


class Config:
    # =========================
    # Path Configuration
    # =========================
    INPUT_DIR = "./input"
    TRAIN_IMAGES_DIR = os.path.join(INPUT_DIR, "train_images")
    TEST_IMAGES_DIR = os.path.join(INPUT_DIR, "test_images")

    # Metadata paths (generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output and Caching
    WORKING_DIR = "./working"
    # Specific cache directory for this idea as requested
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_10")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # =========================
    # Data Hyperparameters
    # =========================
    # Image Preprocessing
    IMG_SIZE = (256, 256)  # Resizing for ResNet input
    NUM_SLICES = 64  # Sequence length
    IN_CHANNELS = 3  # 2.5D: z-1, z, z+1

    # Standard Bone Window
    WINDOW_LEVEL = 400
    WINDOW_WIDTH = 1800

    # =========================
    # Model Hyperparameters
    # =========================
    BACKBONE = "resnet18"
    NUM_CLASSES = 8  # C1-C7 + Patient Overall. Cite solution_lesson_node_00045
    HIDDEN_DIM = 512  # Feature dimension from backbone
    DROPOUT = 0.0  # No dropout in head as per idea

    # =========================
    # Training Hyperparameters
    # =========================
    BATCH_SIZE = 8
    EPOCHS = 10
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    MAX_GRAD_NORM = 10.0

    # Scheduler
    T_MAX_MULT = 1.5  # T_max = EPOCHS * 1.5
    MIN_LR = 1e-6

    # System
    SEED = 42
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # =========================
    # Debug / Development
    # =========================
    DEBUG = False
    # If DEBUG is True, limit dataset to this many samples
    DEBUG_SAMPLE_SIZE = 50


def seed_everything(seed=42):
    """
    Sets the seed for generating random numbers to ensure reproducibility.
    """
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


# Ensure cache directory exists
os.makedirs(Config.CACHE_DIR, exist_ok=True)
